import functools

from time import sleep
from taf.ul.kpi_selector.utilities.exceptions import MaximumAttemptLimitReached
from taf.ul.kpi_selector.utilities.kpi_logger import (
    log_operation,
    log_iteration,
    log_result,
    log_suppression,
)


class retry_for_n_times:
    def __init__(self, n):
        self._n = n

    def __call__(self, f):

        @functools.wraps(f)
        def wrapper(*args, **kwargs):
            log_operation("Trying '{}' method {} times".format(f.__name__, self._n))

            for attempt in range(self._n):
                log_iteration("Attempt number: {}".format(attempt + 1))
                try:
                    result = f(*args, **kwargs)
                    log_result("Method '{}' succeed".format(f.__name__))
                    return result

                except Exception as ex:
                    log_suppression("Method '{}' failed with: {}('{}')".format(f.__name__, ex.__class__.__name__, ex))
                    continue

            else:
                raise MaximumAttemptLimitReached("Failed {} times while calling '{}' method".format(self._n,
                                                                                                    f.__name__))

        return wrapper


class retry_for_scm_flag:
    _use_default_flag = False

    def __init__(self, n):
        self._n = n

    def __call__(self, f):

        @functools.wraps(f)
        def wrapper(*args, **kwargs):
            if not retry_for_scm_flag._use_default_flag:
                log_operation("Trying '{}' method {} times".format(f.__name__, self._n))

                for attempt in range(self._n):
                    log_iteration("Attempt number: {}".format(attempt + 1))
                    try:
                        result = f(*args, **kwargs)
                        log_result("Method '{}' succeed".format(f.__name__))
                        return result

                    except Exception as ex:
                        log_suppression("Method '{}' failed with: {}('{}')".format(
                            f.__name__, ex.__class__.__name__, ex)
                        )
                        sleep(30)
                        continue
                else:
                    log_operation("Method '{}' failed {} times. Default SCM flag will be used for the whole Test Suite."
                                  .format(f.__name__, self._n))
                    retry_for_scm_flag._use_default_flag = True

            result = "default_flag"
            log_result("Default SCM flag is being used.")
            return result

        return wrapper
